        var port = descriptions[elem["{#NODE}"] + ':' + elem["{#IFNAME}"]];

        elem["{#IFDESCR}"] = port["{#IFDESCR}"];
        elem["{#IFSNMPINDEX}"] = port["{#SNMPINDEX}"];


        switch(elem["{#TYPE}"]) {
            case '0':
                elem["{#TYPE}"] = 'physical';
                break;
            case '1':
                elem["{#TYPE}"] = 'if-group';
                break;
            case '2':
                elem["{#TYPE}"] = 'vlan';
                break;
            case '3':
                elem["{#TYPE}"] = 'undef';
                break;
        };

